create table categories(id bigint primary key generated always as identity,name text not null unique,slug text not null unique,created_at timestamptz default now());
create table products(id bigint primary key generated always as identity,name text not null,description text,price numeric(10,2) not null,sale_price numeric(10,2),sku text unique not null,category_id bigint references categories(id),customizable boolean default false,material text default 'Premium Cotton',care_instructions text,status text default 'active',low_stock_threshold int default 10,created_at timestamptz default now(),updated_at timestamptz default now());
create table product_variants(id bigint primary key generated always as identity,product_id bigint references products(id) on delete cascade,size text not null,color text default 'Black',created_at timestamptz default now());
create table product_images(id bigint primary key generated always as identity,product_id bigint references products(id) on delete cascade,image_url text not null,alt_text text,display_order int default 0,created_at timestamptz default now());
create table inventory(id bigint primary key generated always as identity,product_id bigint references products(id) on delete cascade,variant_id bigint references product_variants(id),stock_quantity int not null default 0,reserved_stock int default 0,created_at timestamptz default now(),updated_at timestamptz default now());
create table user_profiles(id uuid primary key references auth.users(id) on delete cascade,full_name text,email text unique,phone text,is_admin boolean default false,created_at timestamptz default now(),updated_at timestamptz default now());
create table orders(id bigint primary key generated always as identity,order_number text unique not null,user_id uuid references auth.users(id),customer_name text not null,customer_email text not null,customer_phone text not null,shipping_address text not null,shipping_city text not null,shipping_wilaya text not null,delivery_notes text,subtotal numeric(10,2) not null,shipping_cost numeric(10,2) default 0,total numeric(10,2) not null,payment_status text default 'pending',fulfillment_status text default 'new',created_at timestamptz default now(),updated_at timestamptz default now());
create table order_items(id bigint primary key generated always as identity,order_id bigint references orders(id) on delete cascade,product_id bigint references products(id),variant_id bigint references product_variants(id),quantity int not null,unit_price numeric(10,2) not null,personalization jsonb,created_at timestamptz default now());
create table personalizations(id bigint primary key generated always as identity,order_item_id bigint references order_items(id) on delete cascade,customer_id uuid references auth.users(id),text_content text,font_family text,text_size int,position text,rotation int default 0,scale numeric(3,2) default 1,placement text default 'front',artwork_url text,artwork_file_size int,status text default 'pending',admin_notes text,created_at timestamptz default now(),updated_at timestamptz default now());
create index products_status_idx on products(status);create index orders_created_idx on orders(created_at desc);create index inventory_product_idx on inventory(product_id);
